
      .data
      MVF_TMP1: .long 0
      MVF_TMP2: .long 0
      MVF_TMP3: .long 0
      MVF_TMP4: .long 0
              
      MVF_REGISTER_EAX: .long 0
      MVF_REGISTER_EBX: .long 0
      MVF_REGISTER_ECX: .long 0
      MVF_REGISTER_EDX: .long 0
      MVF_REGISTER_ESI: .long 0
      MVF_REGISTER_EDI: .long 0
      MVF_REGISTER_EBP: .long 0
      MVF_REGISTER_ESP: .long 0

      MVF_1BIT_AND_LUT: .long MVF_1BIT_AND_0_LUT, MVF_1BIT_AND_1_LUT
      MVF_1BIT_AND_0_LUT: .long 0, 0
      MVF_1BIT_AND_1_LUT: .long 0, 1

      MVF_1BIT_OR_LUT: .long MVF_1BIT_OR_0_LUT, MVF_1BIT_OR_1_LUT
      MVF_1BIT_OR_0_LUT: .long 0, 1
      MVF_1BIT_OR_1_LUT: .long 1, 1

      MVF_1BIT_XOR_LUT: .long MVF_1BIT_XOR_0_LUT, MVF_1BIT_XOR_1_LUT
      MVF_1BIT_XOR_0_LUT: .long 0, 1
      MVF_1BIT_XOR_1_LUT: .long 1, 0

      MVF_1BIT_NOT_LUT: .long 1, 0
              
      MVF_DISPATCHER_JUMP_ADDRESS: .long 0
      __ARRIVED_AT_DISPATCHER_DEBUG_STR: .asciz "Arrived at the MVF_DISPATCHER"

      MVF_CONDITIONAL_JUMP_LUT: .long 0, MVF_TMP1, 0

      .text
      # ############################## THE DISPATCHER ##############################
      MVF_DISPATCHER:
      push $__ARRIVED_AT_DISPATCHER_DEBUG_STR
      call puts
      add $4, %esp

      # %eax now contains a pointer to a ucontext_t struct
      # which stores the values of all the registers at the moment
      # of the crash (including EIP)
      mov 12(%esp), %eax

      # %ebx now stores the address where we should redirect execution to
      mov MVF_DISPATCHER_JUMP_ADDRESS, %ebx
      
      # This sets the EIP to whatever is stored in MVF_DISPATCHER_JUMP_ADDRESS
      mov %ebx, 76(%eax)

      # The way we currently implement conditional jumps uses
      # register %edi (it sets it to a valid or invalid address and then attempts to dereference it),
      # so we must restore its value (we also suppose that the intentional segfaulty
      # code that brought us here saved the value of %edi in MVF_REGISTER_EDI before using it to trigger
      # the segfault)
      mov MVF_REGISTER_EDI, %edi
      mov %edi, 36(%eax)

      ret
      MVF_DISPATCHER_END:
      # #############################################################################

      MVF_SETUP:
      # This:
      #  - registers MVF_DISPATCHER to be a SIGSEV handler

      # Allocating enough space for:
      #  - struct sigaction (offset: 0 - 140)
      push %ebp
      mov %esp, %ebp
      sub $140, %esp

      # sa_resolver = NULL
      # sa_flags = SIGSEV
      # sa_sigaction = &MVF_DISPATCHER
      movl $0, -4(%ebp)
      movl $4, -8(%ebp)
      movl $MVF_DISPATCHER, -140(%ebp)

      # Putting in eax the address of the struct
      mov %ebp, %eax
      sub $140, %eax

      # Registering the handler: sigaction(SIGSEV, struct sigaction, NULL)
      push $0
      push %eax
      push $11
      call sigaction
      add $12, %esp

      # Poping the frame and returning
      add $140, %esp
      pop %ebp
      ret # can be removed
      MVF_SETUP_END:

      .section .init_array
      .long MVF_SETUP
    
